-- Ask Madhav Seed Data
-- All 18 chapters + 30 key verses

-- ============================================================
-- CHAPTERS (all 18)
-- ============================================================

INSERT INTO chapters (number, title, title_sanskrit, description, verse_count, themes) VALUES
(1,  'Arjuna''s Dilemma',                  'Arjuna Vishada Yoga',         'Arjuna surveys the battlefield at Kurukshetra and is overcome with grief seeing his kinsmen arrayed against him.', 47, ARRAY['grief','doubt','crisis','duty']),
(2,  'The Yoga of Knowledge',              'Sankhya Yoga',                'Krishna begins his teachings: the soul is eternal, duty must be performed, and wisdom leads to liberation.', 72, ARRAY['knowledge','soul','duty','detachment','karma yoga']),
(3,  'The Yoga of Action',                 'Karma Yoga',                  'Krishna explains that action is inevitable and that selfless action without attachment is the path.', 43, ARRAY['action','duty','selfless service','leadership']),
(4,  'The Yoga of Wisdom',                 'Jnana Yoga',                  'Krishna reveals his divine nature, the purpose of his incarnations, and the power of transcendental knowledge.', 42, ARRAY['wisdom','knowledge','divine incarnation','sacrifice']),
(5,  'The Yoga of Renunciation',           'Karma Sanyasa Yoga',          'Krishna reconciles action and renunciation: true renunciation is internal detachment, not external withdrawal.', 29, ARRAY['renunciation','detachment','action','liberation']),
(6,  'The Yoga of Meditation',             'Dhyana Yoga',                 'Krishna gives detailed instructions on meditation, mind control, and the path to self-realization.', 47, ARRAY['meditation','self-mastery','mind','yoga','equanimity']),
(7,  'The Yoga of Knowledge and Wisdom',   'Jnana Vijnana Yoga',          'Krishna reveals the nature of the divine, the material world, and how the wise come to know God.', 30, ARRAY['divine nature','knowledge','surrender','maya']),
(8,  'The Yoga of the Imperishable',       'Aksara Brahma Yoga',          'Krishna explains what happens at the time of death and how to attain the supreme destination.', 28, ARRAY['death','liberation','remembrance','the absolute']),
(9,  'The Yoga of Royal Knowledge',        'Raja Vidya Raja Guhya Yoga',  'Krishna reveals the most confidential knowledge: devotion to God is the surest and easiest path.', 34, ARRAY['devotion','divine love','royal knowledge','surrender']),
(10, 'The Yoga of Divine Glories',         'Vibhuti Yoga',                'Krishna describes his divine manifestations and opulences to inspire Arjuna''s faith and devotion.', 42, ARRAY['divine manifestations','glory','faith','opulence']),
(11, 'The Yoga of the Universal Form',     'Vishvarupa Darsana Yoga',     'Krishna reveals his cosmic universal form to Arjuna, showing the infinite nature of the divine.', 55, ARRAY['cosmic form','divine vision','awe','infinite']),
(12, 'The Yoga of Devotion',               'Bhakti Yoga',                 'Krishna describes the qualities of his dear devotees and declares devotional service the highest path.', 20, ARRAY['devotion','bhakti','divine qualities','love']),
(13, 'The Yoga of the Field and Its Knower','Ksetra Ksetrajna Vibhaga Yoga','Krishna distinguishes between the body (field) and the soul (knower of the field).', 35, ARRAY['body','soul','knowledge','nature','self-knowledge']),
(14, 'The Yoga of the Three Modes',        'Gunatraya Vibhaga Yoga',      'Krishna explains the three modes of nature (gunas) and how they bind and can be transcended.', 27, ARRAY['three gunas','nature','liberation','conditioning']),
(15, 'The Yoga of the Supreme Being',      'Purushottama Yoga',           'Krishna describes the eternal tree of material existence and the nature of the Supreme Being.', 20, ARRAY['supreme being','eternal','soul','liberation']),
(16, 'The Yoga of Divine and Demonic Natures','Daivāsura Sampad Vibhaga Yoga','Krishna contrasts divine qualities (leading to liberation) with demonic qualities (leading to bondage).', 24, ARRAY['divine qualities','demonic qualities','virtue','liberation']),
(17, 'The Yoga of Three Divisions of Faith','Sraddhatraya Vibhaga Yoga',  'Krishna explains how faith, food, worship, and charity are classified by the three modes of nature.', 28, ARRAY['faith','worship','food','nature','belief']),
(18, 'The Yoga of Liberation',             'Moksha Sanyasa Yoga',         'The concluding chapter summarizing all teachings, culminating in the supreme instruction to surrender to God alone.', 78, ARRAY['liberation','surrender','conclusion','supreme instruction']);

-- ============================================================
-- VERSES (30 key verses)
-- ============================================================

INSERT INTO verses (chapter_number, verse_number, reference, sanskrit_text, transliteration, hindi_meaning, english_meaning, keywords, themes, practical_guidance) VALUES

(2, 47, '2.47',
 'कर्मण्येवाधिकारस्ते मा फलेषु कदाचन। मा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि॥',
 'karmany evadhikaras te ma phalesu kadachana, ma karma-phala-hetur bhur ma te sango stv akarmani',
 'तुम्हारा अधिकार केवल कर्म करने में है, उसके फलों में कभी नहीं। कर्म के फल की कामना मत करो और न ही अकर्म में आसक्त हो।',
 'You have a right to perform your prescribed duties, but you are not entitled to the fruits of your actions. Never consider yourself the cause of the results of your activities, and never be attached to not doing your duty.',
 ARRAY['duty','action','detachment','results','karma','work','fruits','effort','output'],
 ARRAY['karma yoga','detachment','duty','action without expectation'],
 'Focus entirely on doing your best work today without obsessing over outcomes. When you feel anxious about results, redirect your energy back to the quality of your effort. Ask yourself: Am I giving my full effort right now? — that is all you can control.'),

(2, 20, '2.20',
 'न जायते म्रियते वा कदाचिन्नायं भूत्वा भविता वा न भूयः। अजो नित्यः शाश्वतोऽयं पुराणो न हन्यते हन्यमाने शरीरे॥',
 'na jayate mriyate va kadacin nayam bhutva bhavita va na bhuyah, ajo nityah sasvato ayam purano na hanyate hanyamane sarire',
 'यह आत्मा न कभी जन्म लेती है और न मरती है। यह अजन्मा, नित्य, शाश्वत और पुरातन है।',
 'The soul is never born nor dies at any time. It is unborn, eternal, ever-existing, and primeval. It is not slain when the body is slain.',
 ARRAY['soul','eternal','death','fear','immortal','body','spirit','grief','loss','rebirth'],
 ARRAY['eternal soul','death and rebirth','overcoming fear of death','spiritual identity'],
 'When you grieve the loss of a loved one or fear your own death, remember that the soul is eternal and beyond all destruction. Let this truth bring you comfort — what is real can never be lost.'),

(2, 14, '2.14',
 'मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः। आगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत॥',
 'matra-sparsas tu kaunteya sitosna-sukha-duhkha-dah, agamapayino nityas tams titiksasva bharata',
 'हे कौन्तेय, सुख-दुख ये आने-जाने वाले और अनित्य हैं, इसलिए हे भारत, तुम इन्हें सहन करो।',
 'O son of Kunti, the nonpermanent appearance of happiness and distress are like the appearance and disappearance of winter and summer seasons. One must learn to tolerate them without being disturbed.',
 ARRAY['pain','suffering','pleasure','transient','impermanence','endure','tolerate','seasons','anxiety','happiness','temporary'],
 ARRAY['impermanence','equanimity','tolerating pleasure and pain','emotional resilience'],
 'Whatever pain or difficulty you are experiencing right now, know that it is temporary — like a passing season. Remind yourself: This too shall pass, and I am the calm witness beneath it all.'),

(2, 3, '2.3',
 'क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते। क्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परन्तप॥',
 'klaibyam ma sma gamah partha naitat tvayy upapadyate, ksudram hrdaya-daurbalyam tyaktvoттistha parantapa',
 'हे पार्थ, इस कायरता को मत अपनाओ। हे परंतप, हृदय की इस क्षुद्र दुर्बलता को त्यागकर उठो।',
 'O Partha, do not yield to this degrading impotence. It does not become you. Give up such petty weakness of heart and arise, O chastiser of the enemy.',
 ARRAY['weakness','courage','cowardice','giving up','rise','strength','fear','despair','quit','surrender','overcome'],
 ARRAY['courage','overcoming weakness','rising up','self-discipline'],
 'When you feel like giving up on a job, a goal, or a relationship, Krishna''s words ring clearly: arise. This weakness is not who you are. Take one concrete step today — not a giant leap, just one step — and let that momentum carry you forward.'),

(2, 22, '2.22',
 'वासांसि जीर्णानि यथा विहाय नवानि गृह्णाति नरोऽपराणि। तथा शरीराणि विहाय जीर्णान्यन्यानि संयाति नवानि देही॥',
 'vasansi jirnani yatha vihaya navani grhnati naro aparani, tatha sarirani vihaya jirnany anyani samyati navani dehi',
 'जैसे मनुष्य पुराने वस्त्रों को त्यागकर नए वस्त्र धारण करता है, उसी प्रकार आत्मा पुराने शरीरों को छोड़कर नए शरीर धारण करती है।',
 'As a person puts on new garments, giving up old ones, similarly, the soul accepts new material bodies, giving up the old and useless ones.',
 ARRAY['rebirth','soul','death','new beginning','change','transformation','body','life','renewal'],
 ARRAY['reincarnation','death and rebirth','soul journey','change'],
 'Every ending in your life is also a new beginning. When you face a major change — loss of a job, end of a relationship — see it as the soul discarding old garments for new ones. Embrace this change with openness rather than clinging to what was.'),

(2, 62, '2.62',
 'ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते। सङ्गात्सञ्जायते कामः कामात्क्रोधोऽभिजायते॥',
 'dhyayato visayan pumsah sangas tesupajayate, sangat sanjayate kamah kamat krodho abhijayate',
 'विषयों का चिंतन करने से मनुष्य को उनमें आसक्ति हो जाती है। आसक्ति से काम उत्पन्न होता है और काम से क्रोध।',
 'While contemplating the objects of the senses, a person develops attachment for them, and from such attachment lust develops, and from lust anger arises.',
 ARRAY['attachment','desire','anger','temptation','obsession','addiction','lust','craving','mind'],
 ARRAY['attachment and desire','anger','mental discipline','sense control'],
 'Notice what you are spending your mental energy obsessing over. That repeated contemplation grows into craving, and unmet craving becomes anger. Practice redirecting your attention for even 10 minutes today to something wholesome.'),

(2, 63, '2.63',
 'क्रोधाद्भवति सम्मोहः सम्मोहात्स्मृतिविभ्रमः। स्मृतिभ्रंशाद्बुद्धिनाशो बुद्धिनाशात्प्रणश्यति॥',
 'krodhad bhavati sammohah sammohat smrti-vibhramah, smrti-bhramsad buddhi-naso buddhi-nasat pranasyati',
 'क्रोध से मोह, मोह से स्मृतिभ्रम, स्मृतिभ्रम से बुद्धिनाश और बुद्धिनाश से मनुष्य का पतन होता है।',
 'From anger, complete delusion arises, and from delusion bewilderment of memory. When memory is bewildered, intelligence is lost, and when intelligence is lost one falls down.',
 ARRAY['anger','destruction','delusion','memory','intelligence','downfall','rage','judgment','control','ruin'],
 ARRAY['anger','consequences of anger','mental clarity','self-destruction'],
 'Anger destroys your clarity step by step. Before you respond in anger to someone, pause for 60 seconds. Take three deep breaths. Ask yourself: What would the clearest, wisest version of me do right now?'),

(3, 21, '3.21',
 'यद्यदाचरति श्रेष्ठस्तत्तदेवेतरो जनः। स यत्प्रमाणं कुरुते लोकस्तदनुवर्तते॥',
 'yad yad acarati sresthah tat tad evetaro janah, sa yat pramanam kurute lokas tad anuvartate',
 'श्रेष्ठ पुरुष जो-जो आचरण करता है, सामान्य मनुष्य भी वैसा ही करते हैं।',
 'Whatever action a great person performs, common people follow. And whatever standards they set by exemplary acts, all the world pursues.',
 ARRAY['leadership','example','influence','role model','parenting','responsibility','community','standard','follow'],
 ARRAY['leadership by example','responsibility','influence','setting standards'],
 'You are being watched by those who look up to you — your children, colleagues, or friends — whether you know it or not. Act today as if your actions are setting the standard for those around you.'),

(3, 27, '3.27',
 'प्रकृतेः क्रियमाणानि गुणैः कर्माणि सर्वशः। अहङ्कारविमूढात्मा कर्ताहमिति मन्यते॥',
 'prakrteh kriyamanani gunaih karmani sarvasah, ahankara-vimudhatma kartaham iti manyate',
 'प्रकृति के गुणों द्वारा सभी कर्म किए जाते हैं, परन्तु अहंकार से मोहित मनुष्य सोचता है कि मैं कर्ता हूं।',
 'The spirit soul bewildered by the influence of false ego thinks itself the doer of activities that are in actuality carried out by the three modes of material nature.',
 ARRAY['ego','doer','pride','humility','nature','action','false ego','arrogance','identity'],
 ARRAY['ego and false identity','humility','nature of action','surrender of ego'],
 'Today, when something goes well, practice saying I was an instrument rather than I did this. This subtle shift reduces both pride and anxiety over outcomes.'),

(3, 37, '3.37',
 'काम एष क्रोध एष रजोगुणसमुद्भवः। महाशनो महापाप्मा विद्ध्येनमिह वैरिणम्॥',
 'kama esa krodha esa rajo-guna-samudbhavah, mahasano maha-papma viddhy enam iha vairinam',
 'यह काम और क्रोध रजोगुण से उत्पन्न होते हैं। इन्हें तुम इस संसार में अपना शत्रु जानो।',
 'It is lust only, Arjuna, which is born of contact with the material mode of passion and later transformed into wrath, and which is the all-devouring sinful enemy of this world.',
 ARRAY['desire','anger','enemy','lust','passion','enemy within','self-control','temptation','weakness'],
 ARRAY['desire as enemy','anger','self-mastery','inner obstacles'],
 'Identify the one desire or craving that is causing the most disruption in your life right now. Name it clearly — not with shame, but with honest awareness. Awareness is the first step to mastery.'),

(4, 7, '4.7',
 'यदा यदा हि धर्मस्य ग्लानिर्भवति भारत। अभ्युत्थानमधर्मस्य तदात्मानं सृजाम्यहम्॥',
 'yada yada hi dharmasya glanir bhavati bharata, abhyutthanam adharmasya tadatmanam srjamy aham',
 'हे भारत, जब-जब धर्म की हानि होती है और अधर्म की वृद्धि होती है, तब-तब मैं स्वयं को प्रकट करता हूं।',
 'Whenever and wherever there is a decline in religious practice, O descendant of Bharata, and a predominant rise of irreligion — at that time I descend Myself.',
 ARRAY['dharma','justice','righteousness','divine intervention','hope','faith','evil','good','purpose'],
 ARRAY['divine protection','dharma','hope','cosmic justice'],
 'When you see injustice around you and feel helpless, the universe has a self-correcting force. Your role is to be the representative of dharma in your small sphere. Do one righteous act today that you might otherwise leave undone.'),

(4, 8, '4.8',
 'परित्राणाय साधूनां विनाशाय च दुष्कृताम्। धर्मसंस्थापनार्थाय सम्भवामि युगे युगे॥',
 'paritranaya sadhunam vinasaya ca duskrtam, dharma-samsthapanarthaya sambhavami yuge yuge',
 'साधुओं की रक्षा के लिए, दुष्टों के विनाश के लिए और धर्म की स्थापना के लिए मैं युग-युग में प्रकट होता हूं।',
 'To deliver the pious and to annihilate the miscreants, as well as to reestablish the principles of dharma, I Myself appear, millennium after millennium.',
 ARRAY['protection','justice','good','evil','dharma','faith','divine','righteousness','deliverance'],
 ARRAY['divine protection','dharma','cosmic justice','faith'],
 'Trust that goodness is ultimately protected by the universe. Keep doing good without calculating its reward — good is never truly abandoned.'),

(4, 38, '4.38',
 'न हि ज्ञानेन सदृशं पवित्रमिह विद्यते। तत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति॥',
 'na hi jnanena sadrsam pavitram iha vidyate, tat svayam yoga-samsiddhah kalenatmani vindati',
 'इस संसार में ज्ञान के समान कोई पवित्र करने वाली वस्तु नहीं है।',
 'In this world, there is nothing so sublime and pure as transcendental knowledge. Such knowledge is the mature fruit of all mysticism.',
 ARRAY['knowledge','wisdom','learning','purity','self-realization','study','growth','education','insight'],
 ARRAY['knowledge and wisdom','self-realization','purification','spiritual growth'],
 'Commit to learning something of genuine depth today — not just consuming content, but reflecting on a truth that challenges how you see yourself and the world. Even 15 minutes of deep study cultivates wisdom.'),

(5, 10, '5.10',
 'ब्रह्मण्याधाय कर्माणि सङ्गं त्यक्त्वा करोति यः। लिप्यते न स पापेन पद्मपत्रमिवाम्भसा॥',
 'brahmany adhaaya karmani sangam tyaktva karoti yah, lipyate na sa papena padma-patram ivambhasa',
 'जो मनुष्य सभी कर्म ब्रह्म को समर्पित करके आसक्ति को त्यागकर कर्म करता है, वह पाप से लिप्त नहीं होता जैसे कमल का पत्ता जल से।',
 'One who performs his duty without attachment, surrendering the results unto the Supreme Lord, is unaffected by sinful action, as the lotus leaf is untouched by water.',
 ARRAY['surrender','offering','detachment','guilt','sin','lotus','action','purity','karma','God'],
 ARRAY['offering actions to God','detachment','freedom from guilt','karma yoga'],
 'When guilt from past actions weighs on you, mentally offer each action today to something larger than yourself — God, the universe, or the greater good. Like a lotus leaf, you can remain untouched by the muddy waters of consequence.'),

(6, 5, '6.5',
 'उद्धरेदात्मनात्मानं नात्मानमवसादयेत्। आत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः॥',
 'uddhared atmanatmanam natmanam avasadayet, atmaiva hy atmano bandhur atmaiva ripur atmanah',
 'मनुष्य को चाहिए कि वह अपने आप को अपने द्वारा उठाए और अपने आप को नीचे न गिरने दे।',
 'One must deliver himself with the help of his mind, and not degrade himself. The mind is the friend of the conditioned soul, and his enemy as well.',
 ARRAY['self-help','mind','friend','enemy','lift','elevate','self-improvement','discipline','inner strength','rescue'],
 ARRAY['self-mastery','mind as friend or enemy','self-improvement','personal responsibility'],
 'No one can save you but yourself. This is not harsh — it is empowering. Identify one area where you have been waiting for external rescue and take one self-directed action in that area today.'),

(6, 6, '6.6',
 'बन्धुरात्मात्मनस्तस्य येनात्मैवात्मना जितः। अनात्मनस्तु शत्रुत्वे वर्तेतात्मैव शत्रुवत्॥',
 'bandhur atmatmanas tasya yenatmaiva tmanatmaiva jitah, anatmanas tu satrutve vartetatmaiva satru-vat',
 'जिस मनुष्य ने अपने मन को जीत लिया है, उसके लिए मन ही उसका मित्र है। परन्तु जिसने मन को नहीं जीता, उसके लिए मन ही शत्रु है।',
 'For one who has conquered the mind, the Supersoul is already reached, for he has attained tranquility. To such a person happiness and distress, heat and cold, honor and dishonor are all the same.',
 ARRAY['mind','self-control','mastery','equanimity','peace','enemy within','discipline','meditation','tranquility'],
 ARRAY['mind control','equanimity','self-mastery','inner peace'],
 'Your mind is either your greatest ally or your most persistent enemy. Today, when a negative thought arises, simply observe it without engaging. This witnessing practice, done consistently, is how the mind becomes your friend.'),

(6, 35, '6.35',
 'असंशयं महाबाहो मनो दुर्निग्रहं चलम्। अभ्यासेन तु कौन्तेय वैराग्येण च गृह्यते॥',
 'asamsayam maha-baho mano durnigraham calam, abhyasena tu kaunteya vairagyena ca grhyate',
 'हे महाबाहो, निःसंदेह मन बड़ा चंचल और कठिनाई से वश में होने वाला है। परन्तु यह अभ्यास और वैराग्य से वश में किया जा सकता है।',
 'O mighty-armed son of Kunti, it is undoubtedly very difficult to curb the restless mind, but it is possible with suitable practice and by detachment.',
 ARRAY['meditation','mind','restless','practice','discipline','focus','concentration','distracted','control','habit'],
 ARRAY['meditation and practice','mind control','discipline','detachment'],
 'Start with just 5 minutes of meditation daily. Do not expect perfection. Simply return to the breath each time the mind wanders. Consistency over weeks transforms the mind.'),

(7, 19, '7.19',
 'बहूनां जन्मनामन्ते ज्ञानवान्मां प्रपद्यते। वासुदेवः सर्वमिति स महात्मा सुदुर्लभः॥',
 'bahunam janmanam ante jnanavaan mam prapadyate, vasudevah sarvam iti sa mahatma su-durlabhah',
 'अनेक जन्मों के अंत में ज्ञानी मुझे प्राप्त होता है। वासुदेव ही सब कुछ है — ऐसा महात्मा अत्यंत दुर्लभ है।',
 'After many births and deaths, one who is actually in knowledge surrenders unto Me, knowing Me to be the cause of all causes and all that is. Such a great soul is very rare.',
 ARRAY['surrender','wisdom','God','unity','rare','divine','knowledge','liberation','oneness','faith'],
 ARRAY['surrender to God','ultimate knowledge','oneness','liberation'],
 'True wisdom is not accumulation of information but the lived recognition that everything around you is an expression of the divine. Practice seeing God in the ordinary today.'),

(9, 22, '9.22',
 'अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते। तेषां नित्याभियुक्तानां योगक्षेमं वहाम्यहम्॥',
 'ananyash cintayanto mam ye janah paryupasate, tesam nityabhiyuktanam yoga-ksemam vahamy aham',
 'जो भक्त मुझे अनन्य भाव से निरंतर उपासना करते हैं, उन नित्ययुक्त भक्तों का योगक्षेम मैं स्वयं वहन करता हूं।',
 'But those who always worship Me with exclusive devotion — to them I carry what they lack, and I preserve what they have.',
 ARRAY['devotion','trust','providence','God provides','faith','worship','protection','abundance','security','worry'],
 ARRAY['devotion','divine providence','trust','faith'],
 'If you are anxious about finances or an uncertain future, this verse is a direct promise. Today, release one worry to God and replace it with one act of sincere gratitude.'),

(9, 26, '9.26',
 'पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति। तदहं भक्त्युपहृतमश्नामि प्रयतात्मनः॥',
 'patram puspam phalam toyam yo me bhaktya prayacchati, tad aham bhakty-upahrtam asnami prayatatmanah',
 'जो भक्त मुझे पत्र, पुष्प, फल और जल भक्तिपूर्वक अर्पित करता है, उस शुद्धात्मा का अर्पण मैं स्वीकार करता हूं।',
 'If one offers Me with love and devotion a leaf, a flower, a fruit or water, I will accept it.',
 ARRAY['devotion','offering','simplicity','love','God','worship','humility','acceptance','prayer','gratitude'],
 ARRAY['devotion','love and surrender','simplicity of devotion','God grace'],
 'You do not need elaborate rituals to connect with the divine. Offer whatever you have — a simple prayer, a flower, a glass of water — with genuine love. The sincerity of your heart matters infinitely more than the grandeur of your offering.'),

(10, 20, '10.20',
 'अहमात्मा गुडाकेश सर्वभूताशयस्थितः। अहमादिश्च मध्यं च भूतानामन्त एव च॥',
 'aham atma gudakesa sarva-bhutasaya-sthitah, aham adis ca madhyam ca bhutanam anta eva ca',
 'हे गुडाकेश, मैं सभी प्राणियों के हृदय में स्थित आत्मा हूं। मैं ही सभी प्राणियों का आदि, मध्य और अंत हूं।',
 'I am the Self, O Gudakesa, seated in the hearts of all creatures. I am the beginning, the middle and the end of all beings.',
 ARRAY['God','self','divine within','soul','presence','unity','all beings','inner divine','consciousness','heart'],
 ARRAY['divine immanence','God within','unity of all life','self-realization'],
 'The divine is seated within your own heart right now. Sit quietly for 5 minutes today, place your hand on your heart, and simply feel the presence there. This is the beginning of real connection.'),

(12, 13, '12.13',
 'अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च। निर्ममो निरहङ्कारः समदुःखसुखः क्षमी॥',
 'advestha sarva-bhutanam maitrah karuna eva ca, nirmamo nirahankara sama-duhkha-sukhah ksami',
 'जो सभी प्राणियों से द्वेष नहीं रखता, सबका मित्र और दयालु है, ममता और अहंकार से रहित है, सुख-दुख में समभाव रखता है।',
 'One who is not envious but is a kind friend to all living entities, who does not think himself a proprietor and is free from false ego, who is equal in both happiness and distress, who is tolerant.',
 ARRAY['compassion','friendship','kindness','envy','jealousy','forgiveness','tolerance','ego','equanimity','relationships'],
 ARRAY['compassion','non-envy','divine qualities','equanimity','relationships'],
 'When you feel jealous of someone''s success, actively wish them well in your heart. Today, identify someone you envy and genuinely pray for their happiness. Notice how it transforms you.'),

(12, 15, '12.15',
 'यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः। हर्षामर्षभयोद्वेगैर्मुक्तो यः स च मे प्रियः॥',
 'yasmanodvijate loko lokan nodvijate ca yah, harsamarsa-bhayodvegair mukto yah sa ca me priyah',
 'जिससे कोई भी उद्विग्न नहीं होता और जो स्वयं किसी से उद्विग्न नहीं होता, जो हर्ष, क्रोध, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।',
 'He by whom no one is put into difficulty and who is not disturbed by anyone, who is equipoised in happiness and distress, fear and anxiety, is very dear to Me.',
 ARRAY['peace','disturb','anxiety','fear','calm','equanimity','relationships','social','harmony','tranquility'],
 ARRAY['equanimity','not disturbing others','inner peace','divine qualities'],
 'Today, practice being the calm center in your interactions — neither a source of turbulence nor easily agitated by it.'),

(13, 2, '13.2',
 'क्षेत्रज्ञं चापि मां विद्धि सर्वक्षेत्रेषु भारत। क्षेत्रक्षेत्रज्ञयोर्ज्ञानं यत्तज्ज्ञानं मतं मम॥',
 'ksetra-jnam capi mam viddhi sarva-ksetresu bharata, ksetra-ksetrajnayor jnanam yat taj jnanam matam mama',
 'हे भारत, तुम मुझे सभी क्षेत्रों में क्षेत्रज्ञ के रूप में जानो। क्षेत्र और क्षेत्रज्ञ दोनों का ज्ञान ही सच्चा ज्ञान है।',
 'O scion of Bharata, you should understand that I am also the knower in all bodies, and to understand this body and its knower is called knowledge. That is My opinion.',
 ARRAY['knowledge','body','soul','field','knower','wisdom','identity','self-knowledge','consciousness'],
 ARRAY['knowledge of field and knower','self-knowledge','body and soul','consciousness'],
 'You are not just the body but the conscious witness within. Today, notice moments when you get completely lost in emotions or thoughts — and gently ask: Who is aware of all this?'),

(14, 5, '14.5',
 'सत्त्वं रजस्तम इति गुणाः प्रकृतिसम्भवाः। निबध्नन्ति महाबाहो देहे देहिनमव्ययम्॥',
 'sattvam rajas tama iti gunah prakrti-sambhavah, nibadhnanti maha-baho dehe dehinam avyayam',
 'हे महाबाहो, प्रकृति से उत्पन्न सत्त्व, रज और तम — ये तीन गुण अविनाशी देही को शरीर में बांधते हैं।',
 'Material nature consists of three modes — goodness, passion and ignorance. When the eternal living entity comes in contact with nature, he becomes conditioned by these modes.',
 ARRAY['nature','qualities','goodness','passion','ignorance','personality','behavior','conditioning','gunas','character'],
 ARRAY['three gunas','nature and conditioning','self-understanding','transcending conditioning'],
 'Observe your current dominant state today. Are you clear and calm (sattvic)? Active and restless (rajasic)? Or dull and confused (tamasic)? Knowing your state is the first step to elevating it.'),

(15, 7, '15.7',
 'ममैवांशो जीवलोके जीवभूतः सनातनः। मनःषष्ठानीन्द्रियाणि प्रकृतिस्थानि कर्षति॥',
 'mamaivamso jiva-loke jiva-bhutah sanatanah, manah-sasthani indriyani prakrti-sthani karsati',
 'इस जीवलोक में मेरा ही सनातन अंश जीव बनकर मन सहित छह इन्द्रियों को प्रकृति में रहते हुए आकर्षित करता है।',
 'The living entities in this conditioned world are My eternal fragmental parts. Due to conditioned life, they are struggling very hard with the six senses, which include the mind.',
 ARRAY['divine spark','God within','soul','eternal','fragment','struggle','senses','identity','belonging','divine nature'],
 ARRAY['divine nature of the soul','eternal fragment of God','identity','spiritual identity'],
 'You are an eternal fragment of the divine, temporarily clothed in a body. When you feel worthless or insignificant, return to this truth. You carry the divine spark within you.'),

(16, 3, '16.3',
 'तेजः क्षमा धृतिः शौचमद्रोहो नातिमानिता। भवन्ति सम्पदं दैवीमभिजातस्य भारत॥',
 'tejah ksama dhrtih saucam adroho natimanita, bhavanti sampadam daivim abhijatasya bharata',
 'तेज, क्षमा, धैर्य, शुद्धता, द्रोह का अभाव और अभिमान का न होना — ये दैवी सम्पदा के गुण हैं।',
 'Splendor, forgiveness, fortitude, cleanliness, freedom from envy and the passion for honor — these qualities belong to godly people.',
 ARRAY['courage','forgiveness','fortitude','purity','humility','divine qualities','character','virtue','strength','nobility'],
 ARRAY['divine qualities','character','virtue','spiritual development'],
 'Choose one divine quality to consciously practice today. If forgiveness is your challenge, forgive one small slight. If fortitude is needed, hold your ground with calm strength. Character is built one virtue at a time.'),

(17, 3, '17.3',
 'सत्त्वानुरूपा सर्वस्य श्रद्धा भवति भारत। श्रद्धामयोऽयं पुरुषो यो यच्छ्रद्धः स एव सः॥',
 'sattvanurupaa sarvasya sraddha bhavati bharata, sraddha-mayo ayam puruso yo yac-chraddha sa eva sah',
 'हे भारत, सभी मनुष्यों की श्रद्धा उनकी प्रकृति के अनुसार होती है। जो जैसी श्रद्धा रखता है, वह वैसा ही है।',
 'O scion of Bharata, according to one''s existence under the various modes of nature, one evolves a particular kind of faith. The living being is of a particular faith according to the modes he has acquired.',
 ARRAY['faith','belief','nature','character','identity','purpose','values','self-knowledge','conviction'],
 ARRAY['faith and nature','self-knowledge','belief systems','identity'],
 'Examine your deepest beliefs — about yourself, about others, about the world. Are those beliefs lifting you up or pulling you down? You can consciously cultivate faith in goodness and growth.'),

(18, 65, '18.65',
 'मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु। मामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे॥',
 'man-mana bhava mad-bhakto mad-yaji mam namaskuru, mam evaisyasi satyam te pratijane priyo asi me',
 'मुझमें मन लगाओ, मेरे भक्त बनो, मेरी पूजा करो, मुझे नमस्कार करो। तुम निश्चय ही मुझे प्राप्त होगे — तुम मुझे प्रिय हो।',
 'Always think of Me, become My devotee, worship Me and offer your homage unto Me. Thus you will come to Me without fail. I promise you this because you are My very dear friend.',
 ARRAY['devotion','God','love','prayer','friend','promise','salvation','surrender','beloved','meditation'],
 ARRAY['devotion','divine love','surrender','God promise'],
 'God is saying directly: You are My dear friend. You are not alone, not abandoned, not unloved. Today, speak to God as you would speak to your most trusted friend — openly, simply, without performance.'),

(18, 66, '18.66',
 'सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज। अहं त्वां सर्वपापेभ्यो मोक्षयिष्यामि मा शुचः॥',
 'sarva-dharman parityajya mam ekam saranam vraja, aham tvam sarva-papebhyo moksayisyami ma sucah',
 'सभी धर्मों को छोड़कर केवल मेरी शरण में आ जाओ। मैं तुम्हें सभी पापों से मुक्त कर दूंगा। शोक मत करो।',
 'Abandon all varieties of religion and just surrender unto Me. I shall deliver you from all sinful reactions. Do not fear.',
 ARRAY['surrender','liberation','fear','guilt','forgiveness','relief','freedom','refuge','grace','peace'],
 ARRAY['total surrender','liberation','freedom from fear','divine grace'],
 'Whatever burden you carry — guilt, fear, shame, confusion — lay it down at the feet of the divine today. Surrender is not giving up; it is trusting in something infinitely greater than your individual will.');

